class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

small = Rectangle(2, 3)
big = Rectangle(10, 4)
print(small.area())
print(big.area())

class Thermostat:
    def __init__(self):
        self.__target = 20

    def set_target(self, value):
        if 10 <= value <= 30:
            self.__target = value
        else:
            print("Out of range")

    def get_target(self):
        return self.__target

t = Thermostat()
t.set_target(45)
t.set_target(22)
print(t.get_target())

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def monthly_pay(self):
        return self.salary / 12

class Manager(Employee):
    def __init__(self, name, salary, bonus):
        super().__init__(name, salary)
        self.bonus = bonus

    def monthly_pay(self):
        return super().monthly_pay() + self.bonus / 12

m = Manager("Ada", 36000, 6000)
print(m.name, m.monthly_pay())

class Guitar:
    def play(self):
        return "Strum"

class Drum:
    def play(self):
        return "Boom"

band = [Guitar(), Drum(), Guitar()]
for instrument in band:
    print(instrument.play())

